#!/bin/bash
# luma-tokay-v20: v19 + Android binder/binderfs and container netfilter (Waydroid); DYNAMIC_DEBUG off (clobber zone).
# luma-tokay-v20: v10 kernel (luma/tokay-daily1) + initramfs tokay-luma-initramfs-v2 (hook 89: GDM
# autologin, Mobile presentation) for the shared Luma shell image. Usage: OSTREE_PATH=/ostree/boot.N/luma/<bootcsum>/0 build-tokay-v11.sh
[ -n "${OSTREE_PATH:-}" ] || { echo "OSTREE_PATH required"; exit 1; }
cd /mnt/luma-secondary/luma-build/pixel9-fold
export PROBE_W=/dev/shm/pixel9-tokay-v20 PROBE_BRANCH=luma/tokay-daily1 PROBE_DTB=zumapro-tokay
export PROBE_VERSION=luma-tokay-v20 PROBE_INITRAMFS_DIR=/mnt/luma-secondary/luma-build/pixel9-fold/inputs/tokay-luma-initramfs-v2
export PROBE_CMDLINE="$(sed -n "s/^CMDLINE=//p" candidates/luma-v60/manifest.env | sed -e "s/ luma.fold_debug=1//" -e "s|ostree=[^ ]*|ostree=$OSTREE_PATH|") luma.diag_restart=0 exynosdrm.pkt_go=1"
export PROBE_MODULES="$(cat probe/luma-boot.modules) aoc-channel aoc-usf aoc-usf-iio s5xxx_modem gnss-kepler"
export PROBE_EXTRA_CONFIG="$(cat probe/luma-boot.config) --enable F2FS_FS --enable F2FS_FS_SECURITY --disable DYNAMIC_DEBUG --enable ANDROID_BINDER_IPC --enable ANDROID_BINDERFS --enable NF_TABLES --enable NF_TABLES_INET --enable NF_TABLES_IPV4 --enable NF_TABLES_IPV6 --enable NF_TABLES_ARP --enable NF_TABLES_NETDEV --enable NF_TABLES_BRIDGE --enable NFT_COMPAT --enable NFT_CT --enable NFT_NAT --enable NFT_MASQ --enable NFT_REDIR --enable NFT_REJECT --enable NFT_REJECT_INET --enable NFT_REJECT_IPV4 --enable NFT_REJECT_IPV6 --enable NFT_FIB --enable NFT_FIB_INET --enable NFT_FIB_IPV4 --enable NFT_FIB_IPV6 --enable NFT_LIMIT --enable NFT_LOG --enable NFT_HASH --enable NFT_QUOTA --enable NFT_NUMGEN --enable NFT_CONNLIMIT --enable NF_CONNTRACK_MARK --enable NF_CONNTRACK_LABELS --enable NF_CONNTRACK_ZONES --enable NF_CT_NETLINK --enable NETFILTER_XTABLES_LEGACY --enable IP_NF_IPTABLES_LEGACY --enable IP6_NF_IPTABLES_LEGACY --enable IP_NF_FILTER --enable IP_NF_NAT --enable IP_NF_MANGLE --enable IP_NF_RAW --enable IP_NF_TARGET_MASQUERADE --enable IP_NF_TARGET_REJECT --enable IP6_NF_FILTER --enable IP6_NF_NAT --enable IP6_NF_MANGLE --enable IP6_NF_RAW --enable IP6_NF_TARGET_MASQUERADE --enable IP6_NF_TARGET_REJECT --enable NETFILTER_XT_TARGET_CHECKSUM --enable NETFILTER_XT_TARGET_REDIRECT --enable NETFILTER_XT_TARGET_LOG --enable NETFILTER_XT_MARK --enable NETFILTER_XT_CONNMARK --enable NETFILTER_XT_MATCH_COMMENT --enable NETFILTER_XT_MATCH_MULTIPORT --enable NETFILTER_XT_MATCH_STATE --enable NETFILTER_XT_MATCH_MARK --enable NETFILTER_XT_MATCH_CONNMARK --enable NETFILTER_XT_MATCH_PKTTYPE --enable NETFILTER_XT_MATCH_LIMIT --enable NETFILTER_XT_MATCH_IPRANGE --enable NETFILTER_XT_MATCH_OWNER --enable NETFILTER_XT_MATCH_PHYSDEV --enable BRIDGE_NETFILTER --enable UNIX_DIAG --enable PACKET_DIAG --enable NETLINK_DIAG " JOBS=16
exec luma-heavy bash probe/build-tokay.sh probe candidates/luma-tokay-v20
